29	using namespace op;
30	#ifdef __cplusplus
31	extern "C" {
32	#endif
33	
34	static const size_t FIRST_DIM = 0;
35	static const size_t SECOND_DIM = 1;
36	static const size_t THIRD_DIM = 2;
37	static const size_t FOURTH_DIM = 3;
38	
39	static const int64_t INTERPOLATION_MODE_MIN_VALUE = 0;
40	static const int64_t INTERPOLATION_MODE_MAX_VALUE = 2;
41	static const int64_t INTERPOLATION_MODE_BILINEAR_VALUE = 0;
42	static const int64_t INTERPOLATION_MODE_NEAREST_VALUE = 1;
43	static const int64_t INTERPOLATION_MODE_BICUBIC_VALUE = 2;
44	static const int64_t PADDING_MODE_MIN_VALUE = 0;
45	static const int64_t PADDING_MODE_MAX_VALUE = 2;
46	static const int64_t SPATIAL_GRID_LAST_DIM_SIZE = 2;
47	static const int64_t SPATIAL_DIM_NUM = 4;
48	static const int64_t AICORE_MAX_SIZE_310P = 20480;
49	static const int64_t SUPPORT_CHANNEL_310P = 32;
50	
51	// 根据API定义，需要列出所能支持的所有dtype
52	static const std::initializer_list<op::DataType> DTYPE_SUPPORT_LIST = {op::DataType::DT_FLOAT, op::DataType::DT_FLOAT16,
53	                                                                       op::DataType::DT_BF16, op::DataType::DT_DOUBLE};
54	
55	static bool CheckNotNull(const aclTensor* input, const aclTensor* grid, const aclTensor* out)
56	{
57	    OP_CHECK_NULL(input, return false);
58	    OP_CHECK_NULL(grid, return false);
59	    OP_CHECK_NULL(out, return false);
60	    return true;
61	}
62	
63	static bool CheckRegBaseSuppport(const aclTensor* input, int64_t interpolationMode)
64	{
65	    if (input->GetDataType() != op::DataType::DT_FLOAT && input->GetDataType() != op::DataType::DT_FLOAT16 &&
66	        input->GetDataType() != op::DataType::DT_BF16) {
67	        OP_LOGD("Only support float16, float32 or bfloat16 on AICore, but got data type is %s",
68	                op::ToString(input->GetDataType()).GetString());
69	        return false;
70	    }
71	    bool isRegBaseArch = IsRegBase();
72	    if (isRegBaseArch && interpolationMode == INTERPOLATION_MODE_BILINEAR_VALUE) {
73	        return true;
74	    }
75	    return false;
76	}
77	
78	static bool CheckDtypeValid(const aclTensor* input, const aclTensor* grid, const aclTensor* out)
79	{
80	    // 检查input、grid、out的数据类型是否一致
81	    OP_CHECK_DTYPE_NOT_MATCH(grid, input->GetDataType(), return false);
82	    OP_CHECK_DTYPE_NOT_MATCH(out, input->GetDataType(), return false);
83	    auto curArch = GetCurrentPlatformInfo().GetCurNpuArch();
84	    // 检查input的数据类型是否在gridsampler2d算子的支持列表内
85	    if (curArch == NpuArch::DAV_2002 && input->GetDataType() == op::DataType::DT_BF16) {
86	        OP_LOGD("input dtype does not support bf16 on this chip.");
87	        return false;
88	    } else {
89	        OP_CHECK_DTYPE_NOT_SUPPORT(input, DTYPE_SUPPORT_LIST, return false);
90	    }
91	    return true;
92	}
93	
94	static bool CheckAttrValid(int64_t interpolationMode, int64_t paddingMode)
95	{
96	    // 检查interpolationMode 、paddingMode是否在支持范围内
97	    if (interpolationMode < INTERPOLATION_MODE_MIN_VALUE || interpolationMode > INTERPOLATION_MODE_MAX_VALUE) {
98	        OP_LOGE(ACLNN_ERR_PARAM_INVALID,
99	                "interpolationMode %ld should be in support list {0(bilinear), 1(nearest), 2(bicubic)}.",
100	                interpolationMode);
101	        return false;
102	    }
103	
104	    if (paddingMode < PADDING_MODE_MIN_VALUE || paddingMode > PADDING_MODE_MAX_VALUE) {
105	        OP_LOGE(ACLNN_ERR_PARAM_INVALID,
106	                "paddingMode %ld should be in support list {0(zeros), 1(border), 2(reflection)}.", paddingMode);
107	        return false;
108	    }
109	    return true;
110	}
111	
112	static bool CheckShape(const aclTensor* input, const aclTensor* grid, const aclTensor* out)
113	{
114	    const auto& inputShape = input->GetViewShape();
115	    const auto& gridShape = grid->GetViewShape();
116	    const auto& outShape = out->GetViewShape();
117	
118	    OP_CHECK_WRONG_DIMENSION(input, SPATIAL_DIM_NUM, return false);
119	    OP_CHECK_WRONG_DIMENSION(grid, SPATIAL_DIM_NUM, return false);
120	    OP_CHECK_WRONG_DIMENSION(out, SPATIAL_DIM_NUM, return false);
121	
122	    if (inputShape.GetDim(FIRST_DIM) != gridShape.GetDim(FIRST_DIM) ||
123	        inputShape.GetDim(FIRST_DIM) != outShape.GetDim(FIRST_DIM)) {
124	        OP_LOGE(ACLNN_ERR_PARAM_INVALID,
125	                "expect input, grid and out to have same batch size, but got input with shape [%s] \
126	            grid with shape [%s] and out with shape [%s]",
127	                op::ToString(inputShape).GetString(), op::ToString(gridShape).GetString(),
128	                op::ToString(outShape).GetString());
129	        return false;
130	    }
131	    if (inputShape.GetDim(SECOND_DIM) != outShape.GetDim(SECOND_DIM)) {
132	        OP_LOGE(ACLNN_ERR_PARAM_INVALID,
133	                "expect input and out to have same channel size, but got input with shape [%s] \
134	            and out with shape [%s]",
135	                op::ToString(inputShape).GetString(), op::ToString(outShape).GetString());
136	        return false;
137	    }
138	    if (gridShape.GetDim(SECOND_DIM) != outShape.GetDim(THIRD_DIM) ||
139	        gridShape.GetDim(THIRD_DIM) != outShape.GetDim(FOURTH_DIM)) {
140	        OP_LOGE(ACLNN_ERR_PARAM_INVALID,
141	                "expect grid and out to have same H and W size, but got grid with shape [%s] and out with shape [%s]",
142	                op::ToString(gridShape).GetString(), op::ToString(outShape).GetString());
143	        return false;
144	    }
145	    if (inputShape.GetDim(THIRD_DIM) == 0 || inputShape.GetDim(FOURTH_DIM) == 0) {
146	        OP_LOGE(ACLNN_ERR_PARAM_INVALID,
147	                "expect input to have non-empty spatial dimensions, but got input with shape [%s]",
148	                op::ToString(inputShape).GetString());
149	        return false;
150	    }
151	    if (gridShape.GetDim(FOURTH_DIM) != SPATIAL_GRID_LAST_DIM_SIZE) {
152	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "expect grid to have size %ld in last dimension, but got grid with shape [%s]",
153	                SPATIAL_GRID_LAST_DIM_SIZE, op::ToString(gridShape).GetString());
154	        return false;
155	    }
156	    return true;
157	}
158	
159	static aclnnStatus CheckParams(const aclTensor* input, const aclTensor* grid, int64_t interpolationMode,
160	                               int64_t paddingMode, const aclTensor* out)
161	{
162	    // 1. 检查参数是否为空指针
163	    CHECK_RET(CheckNotNull(input, grid, out), ACLNN_ERR_PARAM_NULLPTR);
164	
165	    // 2. 检查输入、输出的数据类型是否在API支持的数据类型范围之内，需要根据api定义校验
166	    CHECK_RET(CheckDtypeValid(input, grid, out), ACLNN_ERR_PARAM_INVALID);
167	
168	    // 3. 检查属性参数是否在支持范围内
169	    CHECK_RET(CheckAttrValid(interpolationMode, paddingMode), ACLNN_ERR_PARAM_INVALID);
170	
171	    // 4. 检查输入、输出的shape匹配关系
172	    CHECK_RET(CheckShape(input, grid, out), ACLNN_ERR_PARAM_INVALID);
173	
174	    return ACLNN_SUCCESS;
175	}
176	
177	static bool CheckAiCpuSupport(int64_t interpolationMode)
178	{
179	    if (interpolationMode == INTERPOLATION_MODE_BICUBIC_VALUE) {
180	        OP_LOGD("interpolation mode bicubic is not support in AICPU.");
181	        return false;
182	    }
183	    return true;
184	}
185	
186	static bool Check310PFullLoadSuppport(const aclTensor* input, int64_t interpolationMode, int64_t paddingMode)
187	{
188	    auto curArch = GetCurrentPlatformInfo().GetCurNpuArch();
189	    if (curArch != NpuArch::DAV_2002) {
190	        OP_LOGD("FullLoad template does not support on this npuArch.");
191	        return false;
192	    }
193	    if (input->GetStorageFormat() == op::Format::FORMAT_NHWC) {
194	        OP_LOGD("FullLoad template input format does not support NHWC.");
195	        return false;
196	    }
197	
198	    const auto& inputShape = input->GetViewShape();
199	    int64_t inputC = inputShape.GetDim(SECOND_DIM);
200	    int64_t inputH = inputShape.GetDim(THIRD_DIM);
201	    int64_t inputW = inputShape.GetDim(FOURTH_DIM);
202	    if (inputC * inputH * inputW < AICORE_MAX_SIZE_310P && interpolationMode == INTERPOLATION_MODE_BILINEAR_VALUE &&
203	        paddingMode == PADDING_MODE_MIN_VALUE) {
204	        OP_LOGD("Support FullLoad Template.");
205	        return true;
206	    }
207	
208	    return false;
209	}
210	
211	static bool CheckAiCoreSuppport(const aclTensor* input, int64_t interpolationMode, int64_t paddingMode)
212	{
213	    // 950芯片非bilinear场景，走到老模板
214	    auto curArch = GetCurrentPlatformInfo().GetCurNpuArch();
215	    if (IsRegBase(curArch) && interpolationMode != INTERPOLATION_MODE_BILINEAR_VALUE) {
216	        if (input->GetDataType() == op::DataType::DT_FLOAT || input->GetDataType() == op::DataType::DT_FLOAT16 ||
217	            input->GetDataType() == op::DataType::DT_BF16) {
218	            return true;
219	        }
220	    }
221	
222	    const auto& inputShape = input->GetViewShape();
223	    if (input->GetDataType() != op::DataType::DT_FLOAT && input->GetDataType() != op::DataType::DT_FLOAT16 &&
224	        input->GetDataType() != op::DataType::DT_BF16) {
225	        OP_LOGD("Only support float16, bfloat16 or float32 on AICore, but got data type is %s",
226	                op::ToString(input->GetDataType()).GetString());
227	        return false;
228	    }
229	    if (curArch == NpuArch::DAV_2201) {
230	        return true;
231	    }
232	
233	    bool is2002ArchSlideWindowSuppport = curArch == NpuArch::DAV_2002 &&
234	                                         input->GetDataType() == op::DataType::DT_FLOAT &&
235	                                         interpolationMode == INTERPOLATION_MODE_BILINEAR_VALUE &&
236	                                         inputShape.GetDim(SECOND_DIM) == SUPPORT_CHANNEL_310P &&
237	                                         paddingMode == PADDING_MODE_MIN_VALUE;
238	
239	    bool is2002Arch = (is2002ArchSlideWindowSuppport ||
240	                       Check310PFullLoadSuppport(input, interpolationMode, paddingMode));
241	
242	    bool is3002Arch = (curArch == NpuArch::DAV_3002 && input->GetDataType() == op::DataType::DT_FLOAT16 &&
243	                       interpolationMode == INTERPOLATION_MODE_BILINEAR_VALUE &&
244	                       inputShape.GetDim(SECOND_DIM) == SUPPORT_CHANNEL_310P && paddingMode == PADDING_MODE_MIN_VALUE);
245	    if (is2002Arch || is3002Arch) {
246	        return true;
247	    }
248	    return false;
249	}
250	
251	static aclnnStatus paramsNotSupport(const aclTensor* input, int64_t interpolationMode, int64_t paddingMode,
252	                                    bool alignCorners)
253	{
254	    std::string alignCornerStr = alignCorners ? "true" : "false";
255	    OP_LOGE(ACLNN_ERR_PARAM_INVALID,
256	            "The op info is not supported. Plsease check op info! DataType support list is %s, got data type is %s. \
257	          interpolationMode support 0(bilinear) , 1(nearest) or 2(bicubic), got interpolationMode is %ld. \
258	          paddingMode support 0(zeros) , 1(border) or 2(reflection), got paddingMode is %ld. \
259	          alignCorners support false and true, got alignCorners is %s. \
260	          Notice that when data type is double, no support interpolation mode is bicubic.",
261	            op::ToString(DTYPE_SUPPORT_LIST).GetString(), op::ToString(input->GetDataType()).GetString(),
262	            interpolationMode, paddingMode, alignCornerStr.c_str());
263	    return ACLNN_ERR_PARAM_INVALID;
264	}
265	
266	aclnnStatus aclnnGridSampler2DGetWorkspaceSize(const aclTensor* input, const aclTensor* grid, int64_t interpolationMode,
267	                                               int64_t paddingMode, bool alignCorners, aclTensor* out,
268	                                               uint64_t* workspaceSize, aclOpExecutor** executor)
269	{
270	    L2_DFX_PHASE_1(aclnnGridSampler2D, DFX_IN(input, grid, interpolationMode, paddingMode, alignCorners), DFX_OUT(out));
271	    // 固定写法，创建OpExecutor
272	    auto uniqueExecutor = CREATE_EXECUTOR();
273	    CHECK_RET(uniqueExecutor.get() != nullptr, ACLNN_ERR_INNER_CREATE_EXECUTOR);
274	
275	    // 固定写法，参数检查
276	    auto ret = CheckParams(input, grid, interpolationMode, paddingMode, out);
277	    CHECK_RET(ret == ACLNN_SUCCESS, ret);
278	
279	    // gridsampler2d算子的空tensor在kernel中支持
280	    if (input->IsEmpty() || grid->IsEmpty()) {
281	        // 根据实际支持情况补充
282	        *workspaceSize = 0;
283	        uniqueExecutor.ReleaseTo(executor);
284	        return ACLNN_SUCCESS;
285	    }
286	
287	    // 固定写法，将输入input转换成连续的tensor
288	    auto inputContiguous = l0op::Contiguous(input, uniqueExecutor.get());
289	    CHECK_RET(inputContiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);
290	
291	    // 固定写法，将输入grid转换成连续的tensor
292	    auto gridContiguous = l0op::Contiguous(grid, uniqueExecutor.get());
293	    CHECK_RET(gridContiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);
294	
295	    const aclTensor* gridSampler2DOut = nullptr;
296	    bool regBase = CheckRegBaseSuppport(input, interpolationMode);
297	    if (CheckAiCoreSuppport(input, interpolationMode, paddingMode)) {
298	        // 310p支持fp16/bf16数据类型, Cast为fp32进行计算
299	        bool dtypeNeedCast = input->GetDataType() == op::DataType::DT_FLOAT16;
300	        if (Check310PFullLoadSuppport(input, interpolationMode, paddingMode) && dtypeNeedCast) {
301	            inputContiguous = l0op::Cast(inputContiguous, op::DataType::DT_FLOAT, uniqueExecutor.get());
302	            gridContiguous = l0op::Cast(gridContiguous, op::DataType::DT_FLOAT, uniqueExecutor.get());
303	        }
304	
305	        // transpose NCHW to NHWC
306	        int64_t schedulerMode = 1;
307	        int64_t perm[4] = {0, 2, 3, 1};
308	        bool channelLast = true;
309	        auto valuePerm = uniqueExecutor.get()->AllocIntArray(perm, 4);
310	        inputContiguous = l0op::Transpose(inputContiguous, valuePerm, uniqueExecutor.get());
311	        OP_LOGD("Lanuch GridSample in AICore. Attrs: [%ld], [%ld], [%d], [%d], [%ld]", interpolationMode, paddingMode,
312	                alignCorners, channelLast, schedulerMode);
313	        gridSampler2DOut = l0op::GridSample(inputContiguous, gridContiguous, interpolationMode, paddingMode,
314	                                            alignCorners, channelLast, schedulerMode, uniqueExecutor.get());
315	
316	        // 310p支持fp16/bf16数据类型, 结果Cast回输入数据类型
317	        if (Check310PFullLoadSuppport(input, interpolationMode, paddingMode) && dtypeNeedCast) {
318	            if (input->GetDataType() == op::DataType::DT_FLOAT16) {
319	                gridSampler2DOut = l0op::Cast(gridSampler2DOut, op::DataType::DT_FLOAT16, uniqueExecutor.get());
320	            }
321	        }
322	    } else if (regBase) {
323	        gridSampler2DOut = l0op::GridSample(inputContiguous, gridContiguous, interpolationMode, paddingMode,
324	                                            alignCorners, false, 0, uniqueExecutor.get());
325	    } else if (CheckAiCpuSupport(interpolationMode)) {
326	        OP_LOGD("Lanuch GridSampler2D in AICPU. Attrs: [%ld], [%ld], [%d]", interpolationMode, paddingMode,
327	                alignCorners);
328	        gridSampler2DOut = l0op::GridSampler2D(inputContiguous, gridContiguous, interpolationMode, paddingMode,
329	                                               alignCorners, uniqueExecutor.get());
330	    } else {
331	        return paramsNotSupport(input, interpolationMode, paddingMode, alignCorners);
332	    }
333	
334	    CHECK_RET(gridSampler2DOut != nullptr, ACLNN_ERR_INNER_NULLPTR);
335	
336	    // 固定写法，将计算结果拷贝到输出out上，out可能是非连续的tensor
337	    auto viewCopyResult = l0op::ViewCopy(gridSampler2DOut, out, uniqueExecutor.get());
338	    CHECK_RET(viewCopyResult != nullptr, ACLNN_ERR_INNER_NULLPTR);
339	
340	    // 固定写法，获取计算过程中需要使用的workspace大小
341	    *workspaceSize = uniqueExecutor->GetWorkspaceSize();
342	    uniqueExecutor.ReleaseTo(executor); // 需要把 uniqueExecutor持有executor转移给executor
343	    return ACLNN_SUCCESS;
344	}
345	
346	aclnnStatus aclnnGridSampler2D(void* workspace, uint64_t workspaceSize, aclOpExecutor* executor, aclrtStream stream)
347	{
348	    L2_DFX_PHASE_2(aclnnGridSampler2D);
349	    // 固定写法，调用框架能力，完成计算
350	    return CommonOpExecutorRun(workspace, workspaceSize, executor, stream);
351	}
352	
353	#ifdef __cplusplus
354	}
355	#endif
356

