17	using Ops::Cv::OpTiling::GET_TILINGKEY;
18	
19	namespace optiling {
20	constexpr uint64_t TILING_OFFSET = 1000000000000UL;
21	
22	uint64_t GridSampleTiling::GetTilingKey() const
23	{
24	    GridSampleDtypeKey dtypeKey = GridSampleDtypeKey::FLOAT32;
25	    if (xDtype == ge::DT_FLOAT16) {
26	        dtypeKey = GridSampleDtypeKey::FLOAT16;
27	    } else if (xDtype == ge::DT_BF16) {
28	        dtypeKey = GridSampleDtypeKey::BFLOAT16;
29	    }
30	
31	    uint64_t tilingKey = GET_TILINGKEY(interpolationMode, dtypeKey, dimValue, schedulerMode, dimension, templateCNum,
32	                                       tempType);
33	    OP_LOGD(context_->GetNodeName(), "schedulerMode:%ld,tilingKey:%zu.", schedulerMode, tilingKey);
34	
35	    return tilingKey % TILING_OFFSET;
36	}
37	
38	ge::graphStatus GridSampleTiling::GetShapeAttrsInfo()
39	{
40	    OP_LOGD(context_->GetNodeName(), "GetShapeAttrsInfo begin.");
41	    auto inputX = context_->GetInputShape(0);
42	    OP_CHECK_NULL_WITH_CONTEXT(context_, inputX);
43	    auto inputXDesc = context_->GetInputDesc(0);
44	    OP_CHECK_NULL_WITH_CONTEXT(context_, inputXDesc);
45	    xDtype = inputXDesc->GetDataType();
46	    auto gridXDesc = context_->GetInputDesc(1);
47	    OP_CHECK_NULL_WITH_CONTEXT(context_, gridXDesc);
48	    auto gridDtype = gridXDesc->GetDataType();
49	    auto xShape = Ops::Cv::OpTiling::EnsureNotScalar(inputX->GetStorageShape());
50	    auto inputGrid = context_->GetInputShape(1);
51	    OP_CHECK_NULL_WITH_CONTEXT(context_, inputGrid);
52	    auto gridShape = Ops::Cv::OpTiling::EnsureNotScalar(inputGrid->GetStorageShape());
53	    OP_LOGD(context_->GetNodeName(), "x shape:%s,grid shape:%s", Ops::Base::ToString(xShape).c_str(),
54	            Ops::Base::ToString(gridShape).c_str());
55	
56	    OP_CHECK_IF((xShape.GetDimNum() != DIM_NUM_4D && xShape.GetDimNum() != DIM_NUM_5D) ||
57	                    (gridShape.GetDimNum() != DIM_NUM_4D && gridShape.GetDimNum() != DIM_NUM_5D),
58	                OP_LOGE(context_->GetNodeName(), "x / grid shape length should be 4 or 5"), return ge::GRAPH_FAILED);
59	    OP_CHECK_IF(xShape.GetDimNum() != gridShape.GetDimNum(),
60	                OP_LOGE(context_->GetNodeName(), "x / grid shape length should be equal."), return ge::GRAPH_FAILED);
61	
62	    OP_CHECK_IF(gridShape.GetDim(0) != xShape.GetDim(0),
63	                OP_LOGE(context_->GetNodeName(), "x / grid shape[0] should be same"), return ge::GRAPH_FAILED);
64	
65	    if (xShape.GetDimNum() == DIM_NUM_5D) {
66	        dimension = 1;
67	        dimValue = gridShape.GetDim(DIM_4);
68	        OP_CHECK_IF(dimValue != DIM_3, OP_LOGE(context_->GetNodeName(), "only support (N, D, H, W, 3) for grid"),
69	                    return ge::GRAPH_FAILED);
70	    } else {
71	        dimension = 0;
72	        dimValue = gridShape.GetDim(DIM_3);
73	        OP_CHECK_IF(dimValue != DIM_2, OP_LOGE(context_->GetNodeName(), "only support (N, H, W, 2) for grid"),
74	                    return ge::GRAPH_FAILED);
75	    }
76	
77	    auto compileInfo = reinterpret_cast<const GridSampleCompileInfo*>(context_->GetCompileInfo());
78	    OP_CHECK_NULL_WITH_CONTEXT(context_, compileInfo);
79	    regBase = compileInfo->regBase;
80	    auto ascendc_platform = platform_ascendc::PlatformAscendC(context_->GetPlatformInfo());
81	    platform_ascendc::SocVersion gridSampleSocVersion = ascendc_platform.GetSocVersion();
82	    bool is310P = gridSampleSocVersion == platform_ascendc::SocVersion::ASCEND310P;
83	
84	    OP_CHECK_IF((is310P && dimension == 0 && xDtype != ge::DT_FLOAT && xDtype != ge::DT_FLOAT16),
85	                OP_LOGE(context_->GetNodeName(), "x datatype only support FLOAT32 or FLOAT16"),
86	                return ge::GRAPH_FAILED);
87	    OP_CHECK_IF((is310P && dimension == 0 && gridDtype != ge::DT_FLOAT && gridDtype != ge::DT_FLOAT16),
88	                OP_LOGE(context_->GetNodeName(), "grid datatype only support FLOAT32 or FLOAT16"),
89	                return ge::GRAPH_FAILED);
90	    OP_CHECK_IF(
91	        (!regBase && dimension == 0 && xDtype != ge::DT_FLOAT && xDtype != ge::DT_FLOAT16 && xDtype != ge::DT_BF16),
92	        OP_LOGE(context_->GetNodeName(), "x datatype only support FLOAT32, FLOAT16, BFLOAT16"),
93	        return ge::GRAPH_FAILED);
94	    OP_CHECK_IF((!regBase && dimension == 0 && gridDtype != ge::DT_FLOAT && gridDtype != ge::DT_FLOAT16 &&
95	                 gridDtype != ge::DT_BF16),
96	                OP_LOGE(context_->GetNodeName(), "grid datatype only support FLOAT32, FLOAT16, BFLOAT16"),
97	                return ge::GRAPH_FAILED);
98	    OP_CHECK_IF(
99	        (regBase && dimension == 0 && xDtype != ge::DT_FLOAT && xDtype != ge::DT_FLOAT16 && xDtype != ge::DT_BF16),
100	        OP_LOGE(context_->GetNodeName(), "x datatype only support FLOAT32, FLOAT16, BFLOAT16"),
101	        return ge::GRAPH_FAILED);
102	    OP_CHECK_IF((regBase && dimension == 0 && gridDtype != ge::DT_FLOAT && gridDtype != ge::DT_FLOAT16 &&
103	                 gridDtype != ge::DT_BF16),
104	                OP_LOGE(context_->GetNodeName(), "grid datatype only support FLOAT32, FLOAT16, BFLOAT16"),
105	                return ge::GRAPH_FAILED);
106	    OP_CHECK_IF((dimension == 1 && xDtype != ge::DT_FLOAT && xDtype != ge::DT_FLOAT16 && xDtype != ge::DT_BF16),
107	                OP_LOGE(context_->GetNodeName(), "x datatype only support FLOAT32, FLOAT16, BFLOAT16"),
108	                return ge::GRAPH_FAILED);
109	    OP_CHECK_IF(
110	        (dimension == 1 && gridDtype != ge::DT_FLOAT && gridDtype != ge::DT_FLOAT16 && gridDtype != ge::DT_BF16),
111	        OP_LOGE(context_->GetNodeName(), "grid datatype only support FLOAT32, FLOAT16, BFLOAT16"),
112	        return ge::GRAPH_FAILED);
113	
114	    auto* attrs = context_->GetAttrs();
115	    OP_CHECK_NULL_WITH_CONTEXT(context_, attrs);
116	    const char* pInterpolationMode = attrs->GetAttrPointer<char>(0);
117	    OP_CHECK_NULL_WITH_CONTEXT(context_, pInterpolationMode);
118	    if (strcmp(pInterpolationMode, "bilinear") == 0) {
119	        interpolationMode = INTERPOLATION_MODE_BILINEAR;
120	    } else if (strcmp(pInterpolationMode, "bicubic") == 0) {
121	        interpolationMode = INTERPOLATION_MODE_BICUBIC;
122	    } else if (strcmp(pInterpolationMode, "nearest") == 0) {
123	        interpolationMode = INTERPOLATION_MODE_NEAREST;
124	    } else {
125	        OP_LOGE(context_->GetNodeName(), "interpolation_mode only support bilinear or nearest or bicubic.");
126	        return ge::GRAPH_FAILED;
127	    }
128	
129	    OP_CHECK_IF(dimension == 1 && interpolationMode == INTERPOLATION_MODE_BICUBIC,
130	                OP_LOGE(context_->GetNodeName(), "GridSampler3D interpolation_mode only support bilinear or nearest"),
131	                return ge::GRAPH_FAILED);
132	
133	    const char* pPaddingMode = attrs->GetAttrPointer<char>(1);
134	    OP_CHECK_NULL_WITH_CONTEXT(context_, pPaddingMode);
135	    if (strcmp(pPaddingMode, "zeros") == 0) {
136	        paddingMode = PADDING_MODE_ZEROS;
137	    } else if (strcmp(pPaddingMode, "border") == 0) {
138	        paddingMode = PADDING_MODE_BORDER;
139	    } else if (strcmp(pPaddingMode, "reflection") == 0) {
140	        paddingMode = PADDING_MODE_REFLECTION;
141	    } else {
142	        OP_LOGE(context_->GetNodeName(), "padding_mode only support zeros or border or reflection.");
143	        return ge::GRAPH_FAILED;
144	    }
145	
146	    const bool* pAlignCorners = attrs->GetAttrPointer<bool>(2);
147	    OP_CHECK_NULL_WITH_CONTEXT(context_, pAlignCorners);
148	    alignCorners = ALIGN_CORNERS_FALSE;
149	    if (*pAlignCorners) {
150	        alignCorners = ALIGN_CORNERS_TRUE;
151	    }
152	
153	    const bool* pChannelLast = attrs->GetAttrPointer<bool>(3);
154	    OP_CHECK_NULL_WITH_CONTEXT(context_, pChannelLast);
155	    channelLast = CHANEL_LAST_FALSE;
156	    if (*pChannelLast) {
157	        channelLast = CHANEL_LAST_TRUE;
158	    }
159	
160	    inN = xShape.GetDim(0);
161	    if (dimension == 0) {
162	        if (channelLast == 0) {
163	            inC = xShape.GetDim(1);
164	            inH = xShape.GetDim(DIM_2);
165	            inW = xShape.GetDim(DIM_3);
166	        } else {
167	            inH = xShape.GetDim(1);
168	            inW = xShape.GetDim(DIM_2);
169	            inC = xShape.GetDim(DIM_3);
170	        }
171	        outH = gridShape.GetDim(1);
172	        outW = gridShape.GetDim(DIM_2);
173	
174	        if ((channelLast == 1) && (strcmp(pInterpolationMode, "bilinear") == 0) &&
175	            (inC * inH * inW <= X_MAX_HWC_FACTOR)) {
176	            tempType = FULL_LOAD_TYPE;
177	            hwFactor = TILING_HW_FACTOR;
178	            if ((outH * outW < BLOCK_NUM) && (inN < coreNumVar * BLOCK_NUM) && is310P) {
179	                context_->SetScheduleMode(SCHEDULE_MODE);
180	            }
181	            OP_LOGD(context_->GetNodeName(), "Get in FullLoad Template.");
182	            if ((inC == 1) && (inH * inW < C1_X_COUNT)) {
183	                templateCNum = 1;
184	            } else if ((inC == NUM_C32) && (inH > MIN_HW_C32) && (inW > MIN_HW_C32)) {
185	                templateCNum = TEMPLATE_C32;
186	            } else {
187	                templateCNum = 0;
188	            }
189	        }
190	
191	        OP_CHECK_IF(inN < 1 || inC < 1 || inH < 1 || inW < 1 || outW < 1 || outH < 1,
192	                    OP_LOGE(context_->GetNodeName(), "Invalid shape. Maybe empty tensor."), return ge::GRAPH_FAILED);
193	        OP_CHECK_IF(inH * inW > static_cast<int64_t>(std::numeric_limits<int32_t>::max()),
194	                    OP_LOGE(context_->GetNodeName(), "no support for H*W of x greater than int32 max value"),
195	                    return ge::GRAPH_FAILED);
196	
197	        const int32_t* pSchedulerMode = attrs->GetAttrPointer<int32_t>(4);
198	        OP_CHECK_NULL_WITH_CONTEXT(context_, pSchedulerMode);
199	        OP_LOGD(context_->GetNodeName(), "scheduler_mode is: %d", *pSchedulerMode);
200	        schedulerMode = *pSchedulerMode;
201	        OP_CHECK_IF(schedulerMode != 0 && schedulerMode != 1,
202	                    OP_LOGE(context_->GetNodeName(), "scheduler_mode only support 0 or 1."), return ge::GRAPH_FAILED);
203	        OP_CHECK_IF(!(*pChannelLast) && schedulerMode == 1,
204	                    OP_LOGE(context_->GetNodeName(), "scheduler_mode support 1 only in the channel last scenario."),
205	                    return ge::GRAPH_FAILED);
206	    } else {
207	        if (channelLast == 0) {
208	            inC = xShape.GetDim(1);
209	            inD = xShape.GetDim(DIM_2);
210	            inH = xShape.GetDim(DIM_3);
211	            inW = xShape.GetDim(DIM_4);
212	        } else {
213	            inD = xShape.GetDim(1);
214	            inH = xShape.GetDim(DIM_2);
215	            inW = xShape.GetDim(DIM_3);
216	            inC = xShape.GetDim(DIM_4);
217	        }
218	        outD = gridShape.GetDim(1);
219	        outH = gridShape.GetDim(DIM_2);
220	        outW = gridShape.GetDim(DIM_3);
221	
222	        OP_CHECK_IF(inN < 1 || inC < 1 || inD < 1 || inH < 1 || inW < 1 || outD < 1 || outW < 1 || outH < 1,
223	                    OP_LOGE(context_->GetNodeName(), "Invalid shape. Maybe empty tensor."), return ge::GRAPH_FAILED);
224	        OP_CHECK_IF(inH * inW * inD > static_cast<int64_t>(std::numeric_limits<int32_t>::max()),
225	                    OP_LOGE(context_->GetNodeName(), "no support for D*H*W of x greater than int32 max value"),
226	                    return ge::GRAPH_FAILED);
227	
228	        // 添加判断是否都为特例场景，若为特例场景schedulerMode为1，否则为默认值0
229	        if (inN == gridShape.GetDim(0) && inD == outD && inH == outH && inW == outW && inD == INT_16 && inH == INT_64 &&
230	            inW == INT_64 && dimValue == DIM_3 && inC == DIM_4 && (inN == INT_22 || inN == INT_88)) {
231	            schedulerMode = 1;
232	        }
233	    }
234	
235	    OP_LOGD(context_->GetNodeName(), "GetShapeAttrsInfo end.");
236	    return ge::GRAPH_SUCCESS;
237	}
