216	static bool CheckAiCoreSuppport(const aclTensor* input, int64_t interpolationMode)
217	{
218	    if (input->GetDataType() != op::DataType::DT_FLOAT && input->GetDataType() != op::DataType::DT_FLOAT16 &&
219	        input->GetDataType() != op::DataType::DT_BF16) {
220	        OP_LOGD("Only support float16, float32 or bfloat16 on AICore, but got data type is %s",
221	                op::ToString(input->GetDataType()).GetString());
222	        return false;
223	    }
224	    auto curArch = GetCurrentPlatformInfo().GetCurNpuArch();
225	    bool is2201Arch = curArch == NpuArch::DAV_2201;
226	    if (is2201Arch) {
227	        return true;
228	    }
229	
230	    // 950芯片非bilinear场景，走到老模板
231	    bool isRegBaseArch = IsRegBase(curArch);
232	    if (isRegBaseArch && interpolationMode != INTERPOLATION_MODE_MIN_VALUE) {
233	        return true;
234	    }
235	    return false;
236	}
