250	static const aclTensor* CheckAndTranspose(const aclTensor* target, const op::Format inputFormat, bool isInput,
251	                                          bool isSpecialcase, aclOpExecutor* executor)
252	{
253	    if (isInput) {
254	        if (inputFormat == op::Format::FORMAT_NCDHW || inputFormat == op::Format::FORMAT_ND) {
255	            if (!isSpecialcase) {
256	                int64_t perm[5] = {0, 2, 3, 4, 1};
257	                auto valuePerm = executor->AllocIntArray(perm, 5);
258	                target = l0op::Transpose(target, valuePerm, executor);
259	            }
260	        } else if (inputFormat == op::Format::FORMAT_NDHWC) {
261	            if (isSpecialcase) {
262	                int64_t perm[5] = {0, 4, 1, 2, 3};
263	                auto valuePerm = executor->AllocIntArray(perm, 5);
264	                target = l0op::Transpose(target, valuePerm, executor);
265	            }
266	        }
267	    } else {
268	        if (inputFormat == op::Format::FORMAT_NDHWC) {
269	            int64_t perm[5] = {0, 2, 3, 4, 1};
270	            auto valuePerm = executor->AllocIntArray(perm, 5);
271	            target = l0op::Transpose(target, valuePerm, executor);
272	        }
273	    }
274	    return target;
275	}
276	
277	static bool CheckSpecialCase(const aclTensor* input, const aclTensor* grid)
278	{
279	    const auto& inputDType = input->GetDataType();
280	    if (inputDType != op::DataType::DT_FLOAT16 && inputDType != op::DataType::DT_FLOAT) {
281	        return false;
282	    }
283	    const auto& inputShape = input->GetViewShape();
284	    const auto& gridShape = grid->GetViewShape();
285	    auto xshape_N = inputShape.GetDim(FIRST_DIM);
286	    int64_t xshape_C = 0;
287	    int64_t xshape_D = 0;
288	    int64_t xshape_H = 0;
289	    int64_t xshape_W = 0;
290	    auto gridshape_N = gridShape.GetDim(FIRST_DIM);
291	    auto gridshape_D = gridShape.GetDim(SECOND_DIM);
292	    auto gridshape_H = gridShape.GetDim(THIRD_DIM);
293	    auto gridshape_W = gridShape.GetDim(FOURTH_DIM);
294	    auto gridshape_3 = gridShape.GetDim(FIFTH_DIM);
295	    const op::Format inputFormat = input->GetStorageFormat();
296	    if (inputFormat == op::Format::FORMAT_NCDHW || inputFormat == op::Format::FORMAT_ND) {
297	        xshape_C = inputShape.GetDim(SECOND_DIM);
298	        xshape_D = inputShape.GetDim(THIRD_DIM);
299	        xshape_H = inputShape.GetDim(FOURTH_DIM);
300	        xshape_W = inputShape.GetDim(FIFTH_DIM);
301	    } else if (inputFormat == op::Format::FORMAT_NDHWC) {
302	        xshape_D = inputShape.GetDim(SECOND_DIM);
303	        xshape_H = inputShape.GetDim(THIRD_DIM);
304	        xshape_W = inputShape.GetDim(FOURTH_DIM);
305	        xshape_C = inputShape.GetDim(FIFTH_DIM);
306	    }
307	    if (xshape_N != gridshape_N || xshape_D != gridshape_D || xshape_H != gridshape_H || xshape_W != gridshape_W ||
308	        xshape_D != INT_16 || xshape_H != INT_64 || xshape_W != INT_64 || gridshape_3 != INT_3) {
309	        return false;
310	    }
311	    return xshape_C == INT_4 && (xshape_N == INT_22 || xshape_N == INT_88);
312	}
