314	aclnnStatus aclnnGridSampler3DGetWorkspaceSize(const aclTensor* input, const aclTensor* grid, int64_t interpolationMode,
315	                                               int64_t paddingMode, bool alignCorners, aclTensor* out,
316	                                               uint64_t* workspaceSize, aclOpExecutor** executor)
317	{
